1	// Git sync for the active working folder — fully compatible with the desktop
2	// app: same libgit2 core, same .type/settings.json, same conflict rule
3	// (conflicts keep local and write the remote as a .conflict.md sibling).
4	//
5	// The primary flow is QR-based: the desktop's "Local network server" card
6	// shows a type2://sync QR; scanning it here (in-app camera, or the system
7	// camera via the deep link) saves the remote and connects, so syncing is one
8	// button afterwards.
9	
10	import { CameraView, useCameraPermissions } from "expo-camera";
11	import { useEffect, useRef, useState } from "react";
12	import {
13	  Modal,
14	  Pressable,
15	  RefreshControl,
16	  ScrollView,
17	  StyleSheet,
18	  Text,
19	  View,
20	} from "react-native";
21	import { useSafeAreaInsets } from "react-native-safe-area-context";
22	
23	import * as core from "@typenotes/mobile-core/core-api";
24	import { getErrorMessage } from "@typenotes/shared/errors";
25	import {
26	  formatCommitSummaryForApp,
27	  formatGitCommitStateLabel,
28	  formatGitCommitTime,
29	} from "@typenotes/shared/format";
30	import { parseSyncDeepLink, type SyncDeepLinkParams } from "@typenotes/shared/sync-link";
31	
32	import { activeProfile, useSettingsStore } from "../state/settings-store";
33	import { useSyncStore } from "../state/sync-store";
34	import { useTheme } from "../theme";
35	import { Button, Field, InlineNote, Section } from "../ui/controls";
36	
37	const SETUP_STEPS = [
38	  "Open the Type app on your computer.",
39	  "In desktop Settings → Sync, press “Start server” (phone and computer on the same Wi-Fi or hotspot).",
40	  "Tap “Scan QR code” below and point the camera at the code on the computer's screen.",
41	  "Tap “Sync now”. That's it — repeat “Sync now” whenever you want to sync.",
42	];
43	
44	export const SyncScreen = () => {
45	  const theme = useTheme();
46	  const insets = useSafeAreaInsets();
47	  const sync = useSyncStore();
48	  const settingsStore = useSettingsStore();
49	  const profile = activeProfile(settingsStore.snapshot);
50	
51	  const [remoteUrl, setRemoteUrl] = useState(profile?.settings.git_remote_url ?? "");
52	  const [branch, setBranch] = useState(profile?.settings.git_branch ?? "main");
53	  const [username, setUsername] = useState(profile?.settings.git_username ?? "");
54	  const [password, setPassword] = useState(profile?.settings.git_password ?? "");
55	  const [sshKey, setSshKey] = useState<string | null>(null);
56	  const [showManual, setShowManual] = useState(false);
57	  const [connectedVia, setConnectedVia] = useState<string | null>(null);
58	
59	  // QR scanner state
60	  const [scannerOpen, setScannerOpen] = useState(false);
61	  const [scanNotice, setScanNotice] = useState<string | null>(null);
62	  const [permission, requestPermission] = useCameraPermissions();
63	  const handledScanRef = useRef(false);
64	
65	  useEffect(() => {
66	    void sync.refresh().catch(() => {});
67	    void core.getSshPublicKey().then(setSshKey).catch(() => {});
68	    // eslint-disable-next-line react-hooks/exhaustive-deps
69	  }, []);
70	
71	  const applyLink = async (link: SyncDeepLinkParams) => {
72	    setRemoteUrl(link.remote);
73	    setBranch(link.branch ?? "main");
74	    try {
75	      await sync.connectFromLink(link);
76	      setConnectedVia(link.name ?? link.remote);
77	    } catch {
78	      // surfaced via store error state
79	    }
80	  };
81	
82	  // A type2://sync deep link (system camera) lands here via the sync store.
83	  const pendingLink = useSyncStore((s) => s.pendingLink);
84	  useEffect(() => {
85	    if (pendingLink) {
86	      sync.setPendingLink(null);
87	      void applyLink(pendingLink);
88	    }
89	    // eslint-disable-next-line react-hooks/exhaustive-deps
90	  }, [pendingLink]);
91	
92	  const openScanner = async () => {
93	    setScanNotice(null);
94	    if (!permission?.granted) {
95	      const result = await requestPermission();
96	      if (!result.granted) {
97	        useSyncStore.setState({
98	          error: "Camera permission is needed to scan the QR code. Enable it in system settings.",
99	        });
100	        return;
101	      }
102	    }
103	    handledScanRef.current = false;
104	    setScannerOpen(true);
105	  };
106	
107	  const onScanned = (data: string) => {
108	    if (handledScanRef.current) {
109	      return;
110	    }
111	    const link = parseSyncDeepLink(data);
112	    if (!link) {
113	      setScanNotice("That QR code is not a Type sync code — look for the one in desktop Settings → Sync.");
114	      return;
115	    }
116	    handledScanRef.current = true;
117	    setScannerOpen(false);
118	    void applyLink(link);
119	  };
120	
121	  const busy = sync.action !== "idle";
122	  const status = sync.status;
123	  const connected = Boolean(status?.repo_initialized && status?.remote_url);
124	
125	  const connectManually = async () => {
126	    try {
127	      await settingsStore.saveGitSettings({
128	        remoteUrl,
129	        branch,
130	        username,
131	        password,
132	        commitMessage: profile?.settings.git_commit_message ?? "Sync notes",
133	      });
134	      await sync.connect({
135	        remote_url: remoteUrl,
136	        branch,
137	        username: username || null,
138	        password: password || null,
139	      });
140	    } catch {
141	      // surfaced via store error state
142	    }
143	  };
144	
145	  return (
146	    <View style={[styles.root, { backgroundColor: theme.colors.background }]}>
147	      <ScrollView
148	        style={styles.scroll}
149	        contentContainerStyle={[
150	          styles.content,
151	          { paddingBottom: insets.bottom + 48 },
152	        ]}
153	        refreshControl={
154	          <RefreshControl
155	            refreshing={sync.action === "refresh"}
156	            onRefresh={() => void sync.refresh().catch(() => {})}
157	          />
158	        }
159	      >
160	      {!connected ? (
161	        <Section title="Sync with your computer">
162	          {SETUP_STEPS.map((step, index) => (
163	            <View key={step} style={styles.stepRow}>
164	              <Text style={[styles.stepNumber, { color: theme.colors.accent }]}>
165	                {index + 1}
166	              </Text>
167	              <Text style={[styles.stepText, { color: theme.colors.text }]}>{step}</Text>
168	            </View>
169	          ))}
170	          <Button title="Scan QR code" onPress={() => void openScanner()} disabled={busy} />
171	          <InlineNote>
172	            You can also point the system Camera app at the QR — it opens Type
173	            and sets everything up the same way.
174	          </InlineNote>
175	        </Section>
176	      ) : null}
177	
178	      <Section title={connected ? "Sync" : "Status"}>
179	        {connectedVia ? (
180	          <Text style={{ color: theme.colors.success }}>
181	            Connected to {connectedVia}.
182	          </Text>
183	        ) : null}
184	        {status ? (
185	          <View style={styles.statusGrid}>
186	            <StatusLine label="Repository" value={status.repo_initialized ? "connected" : "not connected"} />
187	            <StatusLine label="Remote" value={status.remote_url ?? "—"} />
188	            <StatusLine label="Branch" value={status.current_branch ?? "—"} />
189	            <StatusLine
190	              label="Changes"
191	              value={status.has_uncommitted_changes ? "uncommitted changes" : "clean"}
192	            />
193	            <StatusLine label="Ahead / behind" value={`${status.ahead} / ${status.behind}`} />
194	          </View>
195	        ) : (
196	          <InlineNote>Pull to refresh status.</InlineNote>
197	        )}
198	        <Button
199	          title={busy ? "Syncing…" : "Sync now"}
200	          onPress={() => void sync.syncNow().catch(() => {})}
201	          disabled={busy || !connected}
202	        />
203	        <View style={styles.buttonRow}>
204	          <View style={styles.buttonGrow}>
205	            <Button title="Pull only" kind="secondary" onPress={() => void sync.pull().catch(() => {})} disabled={busy || !connected} />
206	          </View>
207	          <View style={styles.buttonGrow}>
208	            <Button title="Push only" kind="secondary" onPress={() => void sync.push().catch(() => {})} disabled={busy || !connected} />
209	          </View>
210	        </View>
211	        {sync.error ? (
212	          <Text style={{ color: theme.colors.danger }}>{sync.error}</Text>
213	        ) : null}
214	        {sync.hint ? <InlineNote>{sync.hint}</InlineNote> : null}
215	      </Section>
216	
217	      {connected ? (
218	        <Section title="Change connection">
219	          <Button title="Scan a new QR code" kind="secondary" onPress={() => void openScanner()} disabled={busy} />
220	        </Section>
221	      ) : null}
222	
223	      <Section title="Advanced">
224	        <Pressable onPress={() => setShowManual((v) => !v)} hitSlop={6}>
225	          <Text style={{ color: theme.colors.accent, fontWeight: "500" }}>
226	            {showManual ? "Hide manual setup" : "Set up manually (git remote URL)"}
227	          </Text>
228	        </Pressable>
229	        {showManual ? (
230	          <>
231	            <Field label="Remote URL" value={remoteUrl} onChangeText={setRemoteUrl} placeholder="git@github.com:you/notes.git" />
232	            <Field label="Branch" value={branch} onChangeText={setBranch} />
233	            <Field label="Username (for https)" value={username} onChangeText={setUsername} />
234	            <Field label="Password / token" value={password} onChangeText={setPassword} secureTextEntry />
235	            <Button title="Save & connect" onPress={() => void connectManually()} disabled={busy || !remoteUrl} />
236	            <InlineNote>
237	              git://, ssh:// and https:// remotes are supported. SSH remotes use the
238	              app key below automatically.
239	            </InlineNote>
240	          </>
241	        ) : null}
242	      </Section>
243	
244	      <Section title="SSH key">
245	        {sshKey ? (
246	          <>
247	            <Text selectable style={[styles.sshKey, { color: theme.colors.text }]}>
248	              {sshKey}
249	            </Text>
250	            <InlineNote>
251	              Add this key to your git host, then connect via an ssh:// remote.
252	              Long-press to copy.
253	            </InlineNote>
254	            <Button
255	              title="Delete key"
256	              kind="danger"
257	              onPress={() =>
258	                void core
259	                  .deleteSshKey()
260	                  .then(() => setSshKey(null))
261	                  .catch(() => {})
262	              }
263	            />
264	          </>
265	        ) : (
266	          <>
267	            <Button
268	              title="Generate key"
269	              kind="secondary"
270	              onPress={() => void core.generateSshKey().then(setSshKey).catch((error) => {
271	                useSyncStore.setState({ error: getErrorMessage(error) });
272	              })}
273	            />
274	            <InlineNote>
275	              Only needed for ssh:// remotes (e.g. GitHub). The local-network QR
276	              flow above doesn't need a key.
277	            </InlineNote>
278	          </>
279	        )}
280	      </Section>
281	
282	      <Section title="History">
283	        {sync.history.length === 0 ? (
284	          <InlineNote>No commits yet.</InlineNote>
285	        ) : (
286	          sync.history.map((entry) => (
287	            <View key={entry.id} style={[styles.commit, { borderBottomColor: theme.colors.border }]}>
288	              <Text style={{ color: theme.colors.text }} numberOfLines={1}>
289	                {formatCommitSummaryForApp(entry.summary)}
290	              </Text>
291	              <Text style={[styles.commitMeta, { color: theme.colors.secondaryText }]}>
292	                {formatGitCommitTime(entry.authored_ms)} · {formatGitCommitStateLabel(entry.sync_state)}
293	                {entry.is_head ? " · HEAD" : ""}
294	              </Text>
295	            </View>
296	          ))
297	        )}
298	      </Section>
299	
300	      </ScrollView>
301	
302	      <Modal
303	        visible={scannerOpen}
304	        animationType="slide"
305	        onRequestClose={() => setScannerOpen(false)}
306	      >
307	        <View style={styles.scanner}>
308	          <CameraView
309	            style={StyleSheet.absoluteFill}
310	            facing="back"
311	            barcodeScannerSettings={{ barcodeTypes: ["qr"] }}
312	            onBarcodeScanned={({ data }) => onScanned(data)}
313	          />
314	          <View style={[styles.scannerOverlay, { paddingTop: insets.top + 16, paddingBottom: insets.bottom + 24 }]}>
315	            <Text style={styles.scannerHint}>
