84	/// Core Git sync gateway. libgit2 operations, SSH key lookup, and notes
85	/// root resolution remain in this outer adapter.
86	pub struct GitSyncAdapter {
87	    app: AppEnv,
88	}
89	
90	impl GitSyncAdapter {
91	    pub fn new(app: AppEnv) -> Self {
92	        Self { app }
93	    }
94	
95	    fn resolve_settings(&self) -> (PathBuf, crate::ProfileSettings) {
96	        let root = crate::ensured_notes_root(&self.app).unwrap_or_default();
