119	        delete_ssh_keypair(&self.app)
120	    }
121	
122	    fn status(&self) -> Result<Self::Status, String> {
123	        let (root, _) = self.resolve_settings();
124	        Ok(build_git_status(&root))
125	    }
126	
127	    fn history(&self, args: Option<Self::HistoryArgs>) -> Result<Vec<Self::History>, String> {
128	        let (root, _) = self.resolve_settings();
129	        let limit = args.and_then(|value| value.limit).unwrap_or(40);
130	        build_git_history(&root, limit)
131	    }
132	
133	    fn connect(&self, args: Self::ConnectArgs) -> Result<Self::Status, String> {
134	        let (root, settings) = self.resolve_settings();
135	
136	        let remote_url = args
137	            .remote_url
138	            .as_deref()
139	            .filter(|s| !s.is_empty())
140	            .unwrap_or(settings.git_remote_url.as_str());
141	        if remote_url.is_empty() {
142	            return Err("Remote URL is required.".to_string());
143	        }
144	
145	        let branch = args
146	            .branch
147	            .as_deref()
148	            .filter(|s| !s.is_empty())
149	            .unwrap_or(settings.git_branch.as_str());
150	
151	        let username = args
152	            .username
153	            .as_deref()
154	            .filter(|s| !s.is_empty())
155	            .or_else(|| {
156	                if !settings.git_username.is_empty() {
157	                    Some(settings.git_username.as_str())
158	                } else {
159	                    None
160	                }
161	            });
162	
163	        let password = args
164	            .password
165	            .as_deref()
166	            .filter(|s| !s.is_empty())
167	            .or_else(|| {
168	                if !settings.git_password.is_empty() {
169	                    Some(settings.git_password.as_str())
170	                } else {
171	                    None
172	                }
173	            });
174	
175	        let repo = ensure_git_repo(&root)?;
176	        prepare_bootstrap_worktree_for_sync(&root, &repo)?;
177	        ensure_origin_remote(&repo, remote_url)?;
178	        let target_branch = resolve_target_branch(&repo, Some(branch.to_string()));
179	        switch_or_prepare_branch(&repo, &target_branch)?;
180	        let ssh_priv = ssh_private_key_if_exists(&self.app);
181	        let ssh_pub = ssh_public_key_if_exists(&self.app);
182	        let fetched = match perform_fetch(
183	            &repo,
184	            &target_branch,
185	            username,
186	            password,
187	            ssh_priv,
188	            ssh_pub,
189	        ) {
190	            Ok(commit) => Some(commit),
191	            Err(error) => {
192	                let lower = error.to_lowercase();
193	                if lower.contains("couldn't find remote ref") {
194	                    None
195	                } else {
196	                    return Err(error);
197	                }
198	            }
199	        };
200	        if let Some(fetched_commit) = fetched {
201	            let analysis = repo
202	                .merge_analysis(&[&fetched_commit])
203	                .map_err(map_git_error)?
204	                .0;
205	            if analysis.is_fast_forward() || analysis.is_up_to_date() {
206	                fast_forward_to(&repo, &target_branch, &fetched_commit)?;
207	            }
208	        }
209	        Ok(build_git_status(&root))
210	    }
211	
212	    fn pull(&self, args: Self::PullArgs) -> Result<Self::Status, String> {
213	        let (root, settings) = self.resolve_settings();
214	        if !git_repo_initialized(&root) {
215	            return Err("Repository is not initialized. Connect a remote first.".to_string());
216	        }
217	
218	        let branch = args
219	            .branch
220	            .as_deref()
221	            .filter(|s| !s.is_empty())
222	            .unwrap_or(settings.git_branch.as_str());
223	
224	        let username = args
225	            .username
226	            .as_deref()
227	            .filter(|s| !s.is_empty())
228	            .or_else(|| {
229	                if !settings.git_username.is_empty() {
230	                    Some(settings.git_username.as_str())
231	                } else {
232	                    None
233	                }
234	            });
235	
236	        let password = args
237	            .password
238	            .as_deref()
239	            .filter(|s| !s.is_empty())
240	            .or_else(|| {
241	                if !settings.git_password.is_empty() {
242	                    Some(settings.git_password.as_str())
243	                } else {
244	                    None
245	                }
246	            });
247	
248	        let repo = open_repo(&root)?;
249	        prepare_bootstrap_worktree_for_sync(&root, &repo)?;
250	        if git_has_changes(&repo) {
251	            return Err("Local changes detected. Push or commit before pulling.".to_string());
252	        }
253	        let target_branch = resolve_target_branch(&repo, Some(branch.to_string()));
254	        switch_or_prepare_branch(&repo, &target_branch)?;
255	        let ssh_priv = ssh_private_key_if_exists(&self.app);
256	        let ssh_pub = ssh_public_key_if_exists(&self.app);
257	        let fetched = perform_fetch(
258	            &repo,
259	            &target_branch,
260	            username,
261	            password,
262	            ssh_priv,
263	            ssh_pub,
264	        )?;
265	        let (analysis, _) = repo.merge_analysis(&[&fetched]).map_err(map_git_error)?;
266	        if analysis.is_up_to_date() {
267	            return Ok(build_git_status(&root));
268	        }
269	        if analysis.is_fast_forward() {
270	            fast_forward_to(&repo, &target_branch, &fetched)?;
271	            return Ok(build_git_status(&root));
272	        }
273	        if analysis.is_normal() {
274	            merge_fetched_commit(&repo, &target_branch, &fetched)?;
275	            return Ok(build_git_status(&root));
276	        }
277	        Err("Pull failed because local and remote history could not be merged.".to_string())
278	    }
279	
280	    fn push(&self, args: Self::PushArgs) -> Result<Self::Status, String> {
281	        let (root, settings) = self.resolve_settings();
282	        if !git_repo_initialized(&root) {
283	            return Err("Repository is not initialized. Connect a remote first.".to_string());
284	        }
285	
286	        let branch = args
287	            .branch
288	            .as_deref()
289	            .filter(|s| !s.is_empty())
290	            .unwrap_or(settings.git_branch.as_str());
291	
292	        let username = args
293	            .username
294	            .as_deref()
295	            .filter(|s| !s.is_empty())
296	            .or_else(|| {
297	                if !settings.git_username.is_empty() {
298	                    Some(settings.git_username.as_str())
299	                } else {
300	                    None
301	                }
302	            });
303	
304	        let password = args
305	            .password
306	            .as_deref()
307	            .filter(|s| !s.is_empty())
308	            .or_else(|| {
309	                if !settings.git_password.is_empty() {
310	                    Some(settings.git_password.as_str())
311	                } else {
312	                    None
313	                }
314	            });
315	
316	        let commit_message = args
317	            .message
318	            .as_deref()
319	            .filter(|s| !s.is_empty())
320	            .unwrap_or(settings.git_commit_message.as_str());
321	
322	        let repo = open_repo(&root)?;
323	        let target_branch = resolve_target_branch(&repo, Some(branch.to_string()));
324	        switch_or_prepare_branch(&repo, &target_branch)?;
325	
326	        let status_before_push = build_git_status(&root);
327	        if !status_before_push.push_required {
328	            return Ok(status_before_push);
329	        }
330	        let _ = commit_all_changes(&repo, commit_message, &target_branch)?;
331	        let ssh_priv = ssh_private_key_if_exists(&self.app);
332	        let ssh_pub = ssh_public_key_if_exists(&self.app);
333	        remote_push(
334	            &repo,
335	            &target_branch,
336	            username,
337	            password,
338	            ssh_priv,
339	            ssh_pub,
340	        )?;
341	        Ok(build_git_status(&root))
342	    }
343	}
344	
345	fn remote_push(
346	    repo: &Repository,
347	    branch: &str,
348	    username: Option<&str>,
349	    password: Option<&str>,
350	    ssh_private_key: Option<PathBuf>,
351	    ssh_public_key: Option<PathBuf>,
352	) -> Result<(), String> {
353	    let callbacks = build_callbacks(
354	        username,
355	        password,
356	        ssh_private_key.clone(),
357	        ssh_public_key.clone(),
358	    );
359	    let mut push_options = PushOptions::new();
360	    push_options.remote_callbacks(callbacks);
361	    let mut remote = repo.find_remote("origin").map_err(map_git_error)?;
362	    remote
363	        .connect_auth(
364	            Direction::Push,
365	            Some(build_callbacks(
366	                username,
367	                password,
368	                ssh_private_key,
369	                ssh_public_key,
370	            )),
371	            None,
372	        )
373	        .map_err(map_git_error)?;
374	    remote
375	        .push(
376	            &[&format!("refs/heads/{0}:refs/heads/{0}", branch)],
377	            Some(&mut push_options),
378	        )
379	        .map_err(map_git_error)?;
380	    let mut local = repo
381	        .find_branch(branch, git2::BranchType::Local)
382	        .map_err(map_git_error)?;
383	    local
384	        .set_upstream(Some(&format!("origin/{}", branch)))
385	        .map_err(map_git_error)?;
386	    Ok(())
387	}
