441	/// Check if a worktree contains only empty system folders and the order file.
442	fn worktree_has_only_bootstrap_artifacts(root: &Path) -> Result<bool, String> {
443	    for entry in fs::read_dir(root).map_err(|err| err.to_string())? {
444	        let entry = entry.map_err(|err| err.to_string())?;
445	        let name = entry.file_name().to_string_lossy().to_string();
446	        if name == ".git" {
447	            continue;
448	        }
449	        let path = entry.path();
450	        let metadata = entry.metadata().map_err(|err| err.to_string())?;
451	        if metadata.is_file() {
452	            if name != ORDER_FILE {
453	                return Ok(false);
454	            }
455	            continue;
456	        }
457	        if metadata.is_dir() {
458	            if !is_system_folder_name(&name) {
459	                return Ok(false);
460	            }
461	            let mut items = fs::read_dir(path).map_err(|err| err.to_string())?;
462	            if items.next().is_some() {
463	                return Ok(false);
464	            }
465	            continue;
466	        }
467	        return Ok(false);
468	    }
469	    Ok(true)
470	}
