472	fn clear_bootstrap_artifacts(root: &Path) -> Result<(), String> {
473	    let order_path = root.join(ORDER_FILE);
474	    if order_path.exists() {
475	        fs::remove_file(&order_path).map_err(|err| err.to_string())?;
476	    }
477	    for folder in PROTECTED_SYSTEM_FOLDERS {
478	        let path = root.join(folder);
479	        if !path.exists() {
480	            continue;
481	        }
482	        let mut items = fs::read_dir(&path).map_err(|err| err.to_string())?;
483	        if items.next().is_none() {
484	            fs::remove_dir(&path).map_err(|err| err.to_string())?;
485	        }
486	    }
487	    Ok(())
488	}
