490	/// Remove bootstrap artifacts before the first sync so the remote content wins.
491	pub fn prepare_bootstrap_worktree_for_sync(
492	    root: &Path,
493	    repo: &Repository,
494	) -> Result<(), String> {
495	    if git_head_has_commit(repo) || !git_has_changes(repo) {
496	        return Ok(());
497	    }
498	    if worktree_has_only_bootstrap_artifacts(root)? {
499	        clear_bootstrap_artifacts(root)?;
500	        return Ok(());
501	    }
502	    Err("Local changes detected. Push or commit before syncing.".to_string())
503	}
