507	fn git_ahead_behind(repo: &Repository, branch: Option<&str>) -> (usize, usize) {
508	    let branch_name = match branch {
509	        Some(value) => value,
510	        None => return (0, 0),
511	    };
512	    let local = match repo.find_branch(branch_name, git2::BranchType::Local) {
513	        Ok(branch) => branch,
514	        Err(_) => return (0, 0),
515	    };
516	    let upstream = match local.upstream() {
517	        Ok(branch) => branch,
518	        Err(_) => return (0, 0),
519	    };
520	    let local_oid = match local.get().target() {
521	        Some(value) => value,
522	        None => return (0, 0),
523	    };
524	    let upstream_oid = match upstream.get().target() {
525	        Some(value) => value,
526	        None => return (0, 0),
527	    };
528	    repo.graph_ahead_behind(local_oid, upstream_oid)
529	        .unwrap_or((0, 0))
530	}
