554	/// Build a comprehensive git sync status snapshot for the frontend.
555	pub fn build_git_status(root: &Path) -> GitSyncStatus {
556	    let repo = Repository::open(root).ok();
557	    let repo_initialized = repo.is_some();
558	    let current_branch = repo.as_ref().and_then(git_current_branch);
559	    let remote_url = repo.as_ref().and_then(git_remote_url);
560	    let has_uncommitted_changes = repo.as_ref().is_some_and(git_has_changes);
561	    let (ahead, behind) = repo
562	        .as_ref()
563	        .map(|repository| git_ahead_behind(repository, current_branch.as_deref()))
564	        .unwrap_or((0, 0));
565	    let push_required = repo
566	        .as_ref()
567	        .map(|repository| {
568	            if has_uncommitted_changes || ahead > 0 {
569	                return true;
570	            }
571	            let branch = current_branch.as_deref();
572	            let has_local_commit = git_branch_has_local_commit(repository, branch);
573	            let has_upstream = git_branch_has_upstream(repository, branch);
574	            has_local_commit && !has_upstream
575	        })
576	        .unwrap_or(false);
577	    GitSyncStatus {
578	        git_available: true,
579	        repo_initialized,
580	        current_branch,
581	        remote_url,
582	        has_uncommitted_changes,
583	        push_required,
584	        ahead,
585	        behind,
586	        notes_root: root.to_string_lossy().to_string(),
587	    }
588	}
