598	/// Build the commit history list with sync state indicators.
599	pub fn build_git_history(
600	    root: &Path,
601	    limit: usize,
602	) -> Result<Vec<GitCommitHistoryEntry>, String> {
603	    if !git_repo_initialized(root) {
604	        return Ok(Vec::new());
605	    }
606	    let repo = open_repo(root)?;
607	    let head_oid = match repo.head().ok().and_then(|head| head.target()) {
608	        Some(oid) => oid,
609	        None => return Ok(Vec::new()),
610	    };
611	    let branch = git_current_branch(&repo);
612	    let upstream_oid = git_upstream_oid(&repo, branch.as_deref());
613	
614	    let mut revwalk = repo.revwalk().map_err(map_git_error)?;
615	    revwalk
616	        .set_sorting(Sort::TOPOLOGICAL | Sort::TIME)
617	        .map_err(map_git_error)?;
618	    revwalk.push(head_oid).map_err(map_git_error)?;
619	
620	    let mut entries = Vec::new();
621	    let max_items = limit.clamp(1, 200);
622	    for oid_result in revwalk.take(max_items) {
623	        let oid = oid_result.map_err(map_git_error)?;
624	        let commit = repo.find_commit(oid).map_err(map_git_error)?;
625	        let summary = commit
626	            .summary()
627	            .map(str::trim)
628	            .filter(|value| !value.is_empty())
629	            .unwrap_or("No commit message")
630	            .to_string();
631	        let author_signature = commit.author();
632	        let author = author_signature
633	            .name()
634	            .or_else(|| author_signature.email())
635	            .map(str::trim)
636	            .filter(|value| !value.is_empty())
637	            .unwrap_or("Unknown author")
638	            .to_string();
639	        let authored_ms = commit.time().seconds().checked_mul(1_000);
640	        let sync_state = if let Some(upstream) = upstream_oid {
641	            if oid == upstream || repo.graph_descendant_of(upstream, oid).unwrap_or(false) {
642	                "synced"
643	            } else {
644	                "local"
645	            }
646	        } else {
647	            "local"
648	        };
649	        let id = oid.to_string();
650	        let short_id = id.chars().take(8).collect::<String>();
651	        entries.push(GitCommitHistoryEntry {
652	            id,
653	            short_id,
654	            summary,
655	            author,
656	            authored_ms,
657	            sync_state: sync_state.to_string(),
658	            is_head: oid == head_oid,
659	        });
660	    }
661	    Ok(entries)
662	}
