687	/// Build git2 callbacks with optional credentials.
688	///
689	/// When `ssh_private_key` is provided the callback will try key-file auth
690	/// before falling back to the SSH agent.
691	pub fn build_callbacks(
692	    username: Option<&str>,
693	    password: Option<&str>,
694	    ssh_private_key: Option<PathBuf>,
695	    ssh_public_key: Option<PathBuf>,
696	) -> RemoteCallbacks<'static> {
697	    let user = username.map(str::to_string);
698	    let pass = password.map(str::to_string);
699	    let mut callbacks = RemoteCallbacks::new();
700	    callbacks.credentials(move |_url, username_from_url, allowed| {
701	        if allowed.contains(CredentialType::USER_PASS_PLAINTEXT) {
702	            if let (Some(user), Some(pass)) = (user.as_deref(), pass.as_deref()) {
703	                return Cred::userpass_plaintext(user, pass);
704	            }
705	        }
706	        if allowed.contains(CredentialType::SSH_KEY) {
707	            // Try key file first.
708	            if let Some(private_key) = &ssh_private_key {
709	                let ssh_user = username_from_url.or(user.as_deref()).unwrap_or("git");
710	                let pub_key = ssh_public_key.as_deref();
711	                if let Ok(cred) = Cred::ssh_key(ssh_user, pub_key, private_key, None) {
712	                    return Ok(cred);
713	                }
714	            }
715	            // Fall back to SSH agent.
716	            if let Some(name) = username_from_url {
717	                if let Ok(cred) = Cred::ssh_key_from_agent(name) {
718	                    return Ok(cred);
719	                }
720	            }
721	            if let Some(user) = user.as_deref() {
722	                if let Ok(cred) = Cred::ssh_key_from_agent(user) {
723	                    return Ok(cred);
724	                }
725	            }
726	        }
727	        if allowed.contains(CredentialType::DEFAULT) {
728	            return Cred::default();
729	        }
730	        Err(git2::Error::from_str(
731	            "No matching Git credentials available for this remote.",
732	        ))
733	    });
734	    callbacks
735	}
