752	/// Switch to the target branch, creating it if it doesn't exist.
753	pub fn switch_or_prepare_branch(repo: &Repository, branch: &str) -> Result<(), String> {
754	    let name = branch.trim();
755	    if name.is_empty() {
756	        return Ok(());
757	    }
758	    let local_ref = format!("refs/heads/{}", name);
759	    if repo.find_reference(&local_ref).is_ok() {
760	        repo.set_head(&local_ref).map_err(map_git_error)?;
761	        repo.checkout_head(Some(CheckoutBuilder::new().safe()))
762	            .map_err(map_git_error)?;
763	        return Ok(());
764	    }
765	    if let Ok(head) = repo.head() {
766	        if let Some(head_oid) = head.target() {
767	            let commit = repo.find_commit(head_oid).map_err(map_git_error)?;
768	            repo.branch(name, &commit, false).map_err(map_git_error)?;
769	            repo.set_head(&local_ref).map_err(map_git_error)?;
770	            repo.checkout_head(Some(CheckoutBuilder::new().safe()))
771	                .map_err(map_git_error)?;
772	            return Ok(());
773	        }
774	    }
775	    repo.set_head(&local_ref).map_err(map_git_error)
776	}
