785	/// Stage all changes and create a commit on the given branch.
786	pub fn commit_all_changes(
787	    repo: &Repository,
788	    message: &str,
789	    branch: &str,
790	) -> Result<Option<Oid>, String> {
791	    let mut index = repo.index().map_err(map_git_error)?;
792	    index
793	        .add_all(["*"].iter(), IndexAddOption::DEFAULT, None)
794	        .map_err(map_git_error)?;
795	    index.write().map_err(map_git_error)?;
796	    if index.is_empty() && !git_has_changes(repo) {
797	        return Ok(None);
798	    }
799	    let tree_id = index.write_tree().map_err(map_git_error)?;
800	    let tree = repo.find_tree(tree_id).map_err(map_git_error)?;
801	    let sig = default_signature(repo)?;
802	    let update_ref = format!("refs/heads/{}", branch);
803	    let oid = match repo.head() {
804	        Ok(head) => {
805	            if let Some(head_oid) = head.target() {
806	                let parent = repo.find_commit(head_oid).map_err(map_git_error)?;
807	                repo.commit(Some(&update_ref), &sig, &sig, message, &tree, &[&parent])
808	                    .map_err(map_git_error)?
809	            } else {
810	                repo.commit(Some(&update_ref), &sig, &sig, message, &tree, &[])
811	                    .map_err(map_git_error)?
812	            }
813	        }
814	        Err(_) => repo
815	            .commit(Some(&update_ref), &sig, &sig, message, &tree, &[])
816	            .map_err(map_git_error)?,
817	    };
818	    repo.set_head(&update_ref).map_err(map_git_error)?;
819	    Ok(Some(oid))
820	}
