824	/// Fetch from "origin" and return the annotated commit for the target branch.
825	pub fn perform_fetch<'a>(
826	    repo: &'a Repository,
827	    branch: &str,
828	    username: Option<&str>,
829	    password: Option<&str>,
830	    ssh_private_key: Option<PathBuf>,
831	    ssh_public_key: Option<PathBuf>,
832	) -> Result<AnnotatedCommit<'a>, String> {
833	    let mut remote = repo.find_remote("origin").map_err(map_git_error)?;
834	    let callbacks = build_callbacks(username, password, ssh_private_key, ssh_public_key);
835	    let mut fetch_options = FetchOptions::new();
836	    fetch_options.remote_callbacks(callbacks);
837	    remote
838	        .fetch(&[branch], Some(&mut fetch_options), None)
839	        .map_err(map_git_error)?;
840	    let fetch_head = repo.find_reference("FETCH_HEAD").map_err(map_git_error)?;
841	    repo.reference_to_annotated_commit(&fetch_head)
842	        .map_err(map_git_error)
843	}
