845	/// Fast-forward the local branch to match the fetched commit.
846	pub fn fast_forward_to(
847	    repo: &Repository,
848	    branch: &str,
849	    fetch_commit: &AnnotatedCommit<'_>,
850	) -> Result<(), String> {
851	    let target_oid = fetch_commit.id();
852	    let local_ref_name = format!("refs/heads/{}", branch);
853	    match repo.find_reference(&local_ref_name) {
854	        Ok(mut local_ref) => {
855	            local_ref
856	                .set_target(target_oid, "Fast-forward")
857	                .map_err(map_git_error)?;
858	            repo.set_head(&local_ref_name).map_err(map_git_error)?;
859	            repo.checkout_head(Some(CheckoutBuilder::new().safe()))
860	                .map_err(map_git_error)?;
861	        }
862	        Err(_) => {
863	            let commit = repo.find_commit(target_oid).map_err(map_git_error)?;
864	            repo.branch(branch, &commit, false).map_err(map_git_error)?;
865	            repo.set_head(&local_ref_name).map_err(map_git_error)?;
866	            repo.checkout_head(Some(CheckoutBuilder::new().safe()))
867	                .map_err(map_git_error)?;
868	        }
869	    }
870	    Ok(())
871	}
