873	/// Build a `.conflict` sibling path: `dir/note.md` → `dir/note.conflict.md`.
874	fn make_conflict_path(rel_path: &str) -> String {
875	    let p = Path::new(rel_path);
876	    let stem = p
877	        .file_stem()
878	        .map(|s| s.to_string_lossy())
879	        .unwrap_or_default();
880	    let new_name = match p.extension().map(|s| s.to_string_lossy()) {
881	        Some(ext) => format!("{stem}.conflict.{ext}"),
882	        None => format!("{stem}.conflict"),
883	    };
884	    p.with_file_name(new_name).to_string_lossy().to_string()
885	}
