887	/// Merge a fetched commit, saving `.conflict` files when there are conflicts.
888	pub fn merge_fetched_commit(
889	    repo: &Repository,
890	    branch: &str,
891	    fetched_commit: &AnnotatedCommit<'_>,
892	) -> Result<(), String> {
893	    let pre_merge_head = repo
894	        .head()
895	        .map_err(map_git_error)?
896	        .peel_to_commit()
897	        .map_err(map_git_error)?;
898	
899	    let mut checkout_options = CheckoutBuilder::new();
900	    checkout_options.safe();
901	    repo.merge(&[fetched_commit], None, Some(&mut checkout_options))
902	        .map_err(map_git_error)?;
903	
904	    let merge_result = (|| -> Result<(), String> {
905	        let head_commit = repo
906	            .head()
907	            .map_err(map_git_error)?
908	            .peel_to_commit()
909	            .map_err(map_git_error)?;
910	        let remote_commit = repo
911	            .find_commit(fetched_commit.id())
912	            .map_err(map_git_error)?;
913	        let mut index = repo.index().map_err(map_git_error)?;
914	
915	        if index.has_conflicts() {
916	            let workdir = repo
917	                .workdir()
918	                .ok_or_else(|| "Repository has no working directory.".to_string())?;
919	
920	            // Collect conflict entries first (can't mutate index while iterating).
921	            let conflict_entries: Vec<_> = index
922	                .conflicts()
923	                .map_err(map_git_error)?
924	                .filter_map(|r| r.ok())
925	                .collect();
926	
927	            let mut resolved_paths = Vec::new();
928	
929	            for entry in &conflict_entries {
930	                let rel_path = entry
931	                    .our
932	                    .as_ref()
933	                    .or(entry.their.as_ref())
934	                    .or(entry.ancestor.as_ref())
935	                    .and_then(|e| std::str::from_utf8(&e.path).ok())
936	                    .map(|s| s.to_string());
937	                let Some(rel_path) = rel_path else {
938	                    continue;
939	                };
940	
941	                match (&entry.our, &entry.their) {
942	                    (Some(ours), Some(theirs)) => {
943	                        // Both sides modified — keep ours, save theirs as .conflict.
944	                        let their_blob = repo.find_blob(theirs.id).map_err(map_git_error)?;
945	                        let conflict_rel = make_conflict_path(&rel_path);
946	                        let conflict_abs = workdir.join(&conflict_rel);
947	                        if let Some(parent) = conflict_abs.parent() {
948	                            let _ = fs::create_dir_all(parent);
949	                        }
950	                        fs::write(&conflict_abs, their_blob.content())
951	                            .map_err(|e| e.to_string())?;
952	
953	                        let our_blob = repo.find_blob(ours.id).map_err(map_git_error)?;
954	                        fs::write(workdir.join(&rel_path), our_blob.content())
955	                            .map_err(|e| e.to_string())?;
956	                    }
957	                    (Some(ours), None) => {
958	                        // They deleted, we modified — keep ours.
959	                        let our_blob = repo.find_blob(ours.id).map_err(map_git_error)?;
960	                        fs::write(workdir.join(&rel_path), our_blob.content())
961	                            .map_err(|e| e.to_string())?;
962	                    }
963	                    (None, Some(theirs)) => {
964	                        // We deleted, they modified — take theirs.
965	                        let their_blob = repo.find_blob(theirs.id).map_err(map_git_error)?;
966	                        let full_path = workdir.join(&rel_path);
967	                        if let Some(parent) = full_path.parent() {
968	                            let _ = fs::create_dir_all(parent);
969	                        }
970	                        fs::write(&full_path, their_blob.content()).map_err(|e| e.to_string())?;
971	                    }
972	                    (None, None) => continue,
973	                }
974	
975	                resolved_paths.push(rel_path);
976	            }
977	
978	            // Resolve each conflict in the index and stage files.
979	            for rel_path in &resolved_paths {
980	                index
981	                    .conflict_remove(Path::new(rel_path))
982	                    .map_err(map_git_error)?;
983	                if workdir.join(rel_path).exists() {
984	                    index.add_path(Path::new(rel_path)).map_err(map_git_error)?;
985	                }
986	                let conflict_rel = make_conflict_path(rel_path);
987	                if workdir.join(&conflict_rel).exists() {
988	                    index
989	                        .add_path(Path::new(&conflict_rel))
990	                        .map_err(map_git_error)?;
991	                }
992	            }
993	
994	            index.write().map_err(map_git_error)?;
995	
996	            if !resolved_paths.is_empty() {
997	                println!(
998	                    "[git] Resolved {} conflict(s) with .conflict files: {}",
999	                    resolved_paths.len(),
1000	                    resolved_paths.join(", ")
1001	                );
1002	            }
1003	        }
1004	
1005	        let tree_id = index.write_tree_to(repo).map_err(map_git_error)?;
1006	        let tree = repo.find_tree(tree_id).map_err(map_git_error)?;
1007	        let signature = default_signature(repo)?;
1008	        let message = format!("Merge origin/{branch} into {branch}");
1009	        repo.commit(
1010	            Some("HEAD"),
1011	            &signature,
1012	            &signature,
1013	            &message,
1014	            &tree,
1015	            &[&head_commit, &remote_commit],
1016	        )
1017	        .map_err(map_git_error)?;
1018	        repo.checkout_head(Some(CheckoutBuilder::new().safe()))
1019	            .map_err(map_git_error)?;
1020	        Ok(())
1021	    })();
1022	
1023	    match merge_result {
1024	        Ok(()) => {
1025	            repo.cleanup_state().map_err(map_git_error)?;
1026	            Ok(())
1027	        }
1028	        Err(error_message) => {
1029	            let cleanup_error = repo.cleanup_state().map_err(map_git_error).err();
1030	            let reset_error = repo
1031	                .reset(pre_merge_head.as_object(), ResetType::Hard, None)
1032	                .map_err(map_git_error)
1033	                .err();
1034	            if cleanup_error.is_none() && reset_error.is_none() {
1035	                return Err(error_message);
1036	            }
1037	            let mut extras = Vec::new();
1038	            if let Some(value) = cleanup_error {
1039	                extras.push(format!("cleanup_state failed: {value}"));
1040	            }
1041	            if let Some(value) = reset_error {
1042	                extras.push(format!("reset failed: {value}"));
1043	            }
1044	            Err(format!(
1045	                "{error_message} Automatic rollback failed: {}",
1046	                extras.join("; ")
1047	            ))
1048	        }
1049	    }
1050	}
