1	//! Local-network ("LAN" / iPhone-hotspot) Git server.
2	//!
3	//! Lets a desktop machine host its own notes repository over the plain `git://`
4	//! protocol with a single button, so a phone on the same Wi-Fi — or connected to
5	//! the phone's personal hotspot — can clone/pull/push without any external
6	//! remote. Implemented by supervising a `git daemon` child process pointed at the
7	//! active profile's notes folder.
8	//!
9	//! Hosting requires the `git` command-line binary and is desktop-only; on mobile
10	//! the commands report `supported = false`.
11	
12	use crate::AppEnv;
13	use serde::Serialize;
14	
15	use mdns_sd::{ServiceDaemon, ServiceEvent};
16	use std::{
17	    collections::HashMap,
18	    time::{Duration, Instant},
19	};
20	
21	use crate::ensured_notes_root;
22	use crate::ports::local_sync::LocalSyncGateway;
23	
24	#[cfg(desktop)]
25	use crate::{commit_all_changes, ensure_git_repo, resolve_target_branch, switch_or_prepare_branch};
26	#[cfg(desktop)]
27	use std::{
28	    net::{IpAddr, TcpListener, UdpSocket},
29	    path::PathBuf,
30	    process::{Child, Command, Stdio},
31	    sync::Mutex,
32	};
33	
34	/// Default git-daemon port (the well-known `git://` port).
35	pub const LOCAL_SYNC_PORT: u16 = 9418;
36	
37	/// Bonjour/mDNS service type the desktop advertises and clients browse for.
38	const MDNS_SERVICE_TYPE: &str = "_typenotes-sync._tcp.local.";
39	
40	#[cfg(desktop)]
41	const GIT_MISSING_MSG: &str = "Hosting a local sync server needs the Git command-line tools. On macOS install them with: xcode-select --install";
42	
43	#[cfg(not(desktop))]
44	const NOT_SUPPORTED_MSG: &str = "Hosting a local sync server is only available in the desktop app.";
45	
46	#[derive(Serialize, Clone)]
47	pub struct LocalSyncServerStatus {
48	    pub supported: bool,
49	    pub git_available: bool,
50	    pub running: bool,
51	    pub host: Option<String>,
52	    pub port: u16,
53	    pub branch: Option<String>,
54	    pub git_url: Option<String>,
55	    pub ssh_url: Option<String>,
56	    pub repo_path: String,
57	    pub error: Option<String>,
58	}
59	
60	/// A server found on the local network via mDNS.
61	#[derive(Serialize, Clone)]
62	pub struct DiscoveredServer {
63	    pub name: String,
64	    pub host: String,
65	    pub port: u16,
66	    pub git_url: String,
67	    pub branch: String,
68	}
69	
70	// ── Running daemon state ─────────────────────────────────────────────────────
71	
72	#[cfg(desktop)]
73	struct RunningDaemon {
74	    child: Child,
75	    host: Option<String>,
76	    served_name: String,
77	    branch: String,
78	    repo_path: PathBuf,
79	    /// mDNS advertisement handle, present when discovery is active.
80	    mdns: Option<MdnsAdvert>,
81	}
82	
83	#[cfg(desktop)]
84	struct MdnsAdvert {
85	    daemon: ServiceDaemon,
86	    fullname: String,
87	}
88	
89	#[cfg(desktop)]
90	static DAEMON: Mutex<Option<RunningDaemon>> = Mutex::new(None);
91	
92	/// Core local-sync gateway. Child-process and mDNS state stay in this
93	/// outer adapter rather than leaking into commands or application services.
94	pub struct LocalSyncAdapter {
95	    app: AppEnv,
96	}
97	
98	impl LocalSyncAdapter {
99	    pub fn new(app: AppEnv) -> Self {
100	        Self { app }
101	    }
102	}
103	
104	impl LocalSyncGateway for LocalSyncAdapter {
105	    type Status = LocalSyncServerStatus;
106	    type Discovered = DiscoveredServer;
107	
108	    fn status(&self) -> Result<Self::Status, String> {
109	        local_sync_server_status(&self.app)
110	    }
111	
112	    fn start(&self) -> Result<Self::Status, String> {
113	        start_local_sync_server_impl(&self.app)
114	    }
115	
116	    fn stop(&self) -> Result<Self::Status, String> {
117	        stop_local_sync_server_impl(&self.app)
118	    }
119	
120	    fn discover(&self, timeout_ms: u64) -> Result<Vec<Self::Discovered>, String> {
121	        discover_local_sync_servers_impl(timeout_ms)
122	    }
123	}
124	
125	// ── Public API (called by the command layer) ─────────────────────────────────
126	
127	pub fn local_sync_server_status(
128	    app: &AppEnv,
129	) -> Result<LocalSyncServerStatus, String> {
130	    let repo_path = ensured_notes_root(app)?.to_string_lossy().to_string();
131	
132	    #[cfg(not(desktop))]
133	    {
134	        Ok(unsupported_status(repo_path))
135	    }
136	
137	    #[cfg(desktop)]
138	    {
139	        let mut guard = DAEMON
140	            .lock()
141	            .map_err(|_| "local sync server state is poisoned".to_string())?;
142	        // Reap a daemon that exited on its own (crash, killed externally).
143	        if let Some(daemon) = guard.as_mut() {
144	            if matches!(daemon.child.try_wait(), Ok(Some(_))) {
145	                *guard = None;
146	            }
147	        }
148	        let git_available = locate_git().is_some();
149	        Ok(match guard.as_ref() {
150	            Some(daemon) => running_status(daemon),
151	            None => idle_status(git_available, repo_path),
152	        })
153	    }
154	}
155	
156	pub fn start_local_sync_server_impl(
157	    app: &AppEnv,
158	) -> Result<LocalSyncServerStatus, String> {
159	    #[cfg(not(desktop))]
160	    {
161	        let _ = app;
162	        Err(NOT_SUPPORTED_MSG.to_string())
163	    }
164	
165	    #[cfg(desktop)]
166	    {
167	        let root = ensured_notes_root(app)?;
168	        let git = locate_git().ok_or_else(|| GIT_MISSING_MSG.to_string())?;
169	
170	        let mut guard = DAEMON
171	            .lock()
172	            .map_err(|_| "local sync server state is poisoned".to_string())?;
173	
174	        // Already running? Return current status (idempotent).
175	        if let Some(daemon) = guard.as_mut() {
176	            if matches!(daemon.child.try_wait(), Ok(None)) {
177	                return Ok(running_status(daemon));
178	            }
179	            // Dead handle — drop it and restart below.
180	            *guard = None;
181	        }
182	
183	        // Make sure the notes folder is a repo, has a commit to clone, and will
184	        // accept pushes to its checked-out branch by updating the working tree.
185	        let repo = ensure_git_repo(&root)?;
186	        repo.config()
187	            .and_then(|mut cfg| cfg.set_str("receive.denyCurrentBranch", "updateInstead"))
188	            .map_err(|e| format!("Failed to configure repo for local sync: {e}"))?;
189	        let branch = resolve_target_branch(&repo, None);
190	        switch_or_prepare_branch(&repo, &branch)?;
191	        // Best-effort initial commit so the phone can pull existing notes; a
192	        // brand-new empty repo is fine too (the phone can push to create it).
193	        let _ = commit_all_changes(&repo, "Initial local sync commit", &branch);
194	        drop(repo);
195	
196	        let parent = root
197	            .parent()
198	            .ok_or_else(|| "Notes folder has no parent directory.".to_string())?;
199	        let served_name = root
200	            .file_name()
201	            .and_then(|name| name.to_str())
202	            .ok_or_else(|| "Notes folder name is not valid UTF-8.".to_string())?
203	            .to_string();
204	
205	        // Pre-flight: give a clear error if the port is already taken.
206	        match TcpListener::bind(("0.0.0.0", LOCAL_SYNC_PORT)) {
207	            Ok(listener) => drop(listener),
208	            Err(e) => {
209	                return Err(format!(
210	                    "Port {LOCAL_SYNC_PORT} is already in use ({e}). Stop any other git daemon and try again."
211	                ))
212	            }
213	        }
214	
215	        let mut child = Command::new(&git)
216	            .arg("daemon")
217	            .arg("--reuseaddr")
218	            .arg("--export-all")
219	            .arg("--enable=upload-pack")
220	            .arg("--enable=receive-pack")
221	            .arg(format!("--base-path={}", parent.display()))
222	            .arg("--listen=0.0.0.0")
223	            .arg(format!("--port={LOCAL_SYNC_PORT}"))
224	            .arg(parent)
225	            .stdin(Stdio::null())
226	            .stdout(Stdio::null())
227	            .stderr(Stdio::null())
228	            .spawn()
229	            .map_err(|e| format!("Failed to start git daemon: {e}"))?;
230	
231	        // Catch an immediate exit (e.g. invalid args / bind race).
232	        std::thread::sleep(Duration::from_millis(150));
233	        if let Ok(Some(status)) = child.try_wait() {
234	            return Err(format!(
235	                "git daemon exited immediately (status {:?}). Port {LOCAL_SYNC_PORT} may be in use.",
236	                status.code()
237	            ));
238	        }
239	
240	        // Advertise over mDNS so phones can auto-discover this server without
241	        // typing or scanning anything. Best-effort: failure never blocks hosting.
242	        let host = detect_lan_ip();
243	        let mdns = host.as_ref().and_then(|ip| {
244	            let git_url = format!("git://{ip}/{served_name}");
245	            advertise_mdns(ip, &served_name, &branch, &git_url)
246	        });
247	
248	        let daemon = RunningDaemon {
249	            child,
250	            host,
251	            served_name,
252	            branch,
253	            repo_path: root,
254	            mdns,
255	        };
256	        let status = running_status(&daemon);
257	        *guard = Some(daemon);
258	        Ok(status)
259	    }
260	}
261	
262	pub fn stop_local_sync_server_impl(
263	    app: &AppEnv,
264	) -> Result<LocalSyncServerStatus, String> {
265	    #[cfg(not(desktop))]
266	    {
267	        let _ = app;
268	        Err(NOT_SUPPORTED_MSG.to_string())
269	    }
270	
271	    #[cfg(desktop)]
272	    {
273	        if let Ok(mut guard) = DAEMON.lock() {
274	            if let Some(daemon) = guard.take() {
275	                teardown_daemon(daemon);
276	            }
277	        }
278	        local_sync_server_status(app)
279	    }
280	}
281	
282	/// Kill the daemon on app exit. Safe to call when nothing is running.
283	#[cfg(desktop)]
284	pub fn shutdown_local_sync_server() {
285	    if let Ok(mut guard) = DAEMON.lock() {
286	        if let Some(daemon) = guard.take() {
287	            teardown_daemon(daemon);
288	        }
289	    }
290	}
291	
292	/// Stop the mDNS advertisement (if any) and kill the git daemon child.
293	#[cfg(desktop)]
294	fn teardown_daemon(mut daemon: RunningDaemon) {
295	    if let Some(advert) = daemon.mdns.take() {
296	        let _ = advert.daemon.unregister(&advert.fullname);
297	        let _ = advert.daemon.shutdown();
298	    }
299	    let _ = daemon.child.kill();
300	    let _ = daemon.child.wait();
301	}
302	
303	// ── Status builders ──────────────────────────────────────────────────────────
304	
305	#[cfg(not(desktop))]
306	fn unsupported_status(repo_path: String) -> LocalSyncServerStatus {
307	    LocalSyncServerStatus {
308	        supported: false,
309	        git_available: false,
310	        running: false,
311	        host: None,
312	        port: LOCAL_SYNC_PORT,
313	        branch: None,
314	        git_url: None,
315	        ssh_url: None,
316	        repo_path,
317	        error: None,
318	    }
319	}
320	
321	#[cfg(desktop)]
322	fn idle_status(git_available: bool, repo_path: String) -> LocalSyncServerStatus {
323	    LocalSyncServerStatus {
324	        supported: true,
325	        git_available,
326	        running: false,
327	        host: None,
328	        port: LOCAL_SYNC_PORT,
329	        branch: None,
330	        git_url: None,
331	        ssh_url: None,
332	        repo_path,
333	        error: None,
334	    }
335	}
336	
337	#[cfg(desktop)]
338	fn running_status(daemon: &RunningDaemon) -> LocalSyncServerStatus {
339	    let git_url = daemon
340	        .host
341	        .as_ref()
342	        .map(|host| format!("git://{host}/{}", daemon.served_name));
343	    let ssh_url = daemon.host.as_ref().map(|host| {
344	        format!(
345	            "ssh://{}@{host}{}",
346	            current_user(),
347	            daemon.repo_path.display()
348	        )
349	    });
350	    LocalSyncServerStatus {
351	        supported: true,
352	        git_available: true,
353	        running: true,
354	        host: daemon.host.clone(),
355	        port: LOCAL_SYNC_PORT,
356	        branch: Some(daemon.branch.clone()),
357	        git_url,
358	        ssh_url,
359	        repo_path: daemon.repo_path.to_string_lossy().to_string(),
360	        error: None,
361	    }
362	}
363	
364	// ── Helpers ──────────────────────────────────────────────────────────────────
365	
366	/// Locate a usable `git` binary: PATH first, then common GUI-app install spots
367	/// (Finder/Dock-launched apps get a minimal PATH, mirroring whisper_env).
368	#[cfg(desktop)]
369	fn locate_git() -> Option<PathBuf> {
370	    let candidates = [
371	        "git",
372	        "/usr/bin/git",
373	        "/opt/homebrew/bin/git",
374	        "/usr/local/bin/git",
375	    ];
376	    candidates.into_iter().map(PathBuf::from).find(|candidate| {
377	        Command::new(candidate)
378	            .arg("--version")
379	            .output()
380	            .map(|out| out.status.success())
381	            .unwrap_or(false)
382	    })
383	}
384	
385	/// Best-effort detection of the outbound LAN/hotspot IPv4. Uses the classic
386	/// "connected UDP socket" trick: connecting does a route lookup and reveals the
387	/// source address for that route without sending any packets. We probe a few
388	/// targets so it works on shared Wi-Fi, on iPhone hotspot (gateway 172.20.10.1),
389	/// and on networks without internet access.
390	#[cfg(desktop)]
391	fn detect_lan_ip() -> Option<String> {
392	    const TARGETS: [&str; 5] = [
393	        "8.8.8.8:80",
394	        "1.1.1.1:80",
395	        "172.20.10.1:80", // iPhone personal-hotspot gateway
396	        "192.168.1.1:80",
397	        "192.168.0.1:80",
398	    ];
399	    for target in TARGETS {
400	        let Ok(socket) = UdpSocket::bind("0.0.0.0:0") else {
401	            continue;
402	        };
403	        if socket.connect(target).is_err() {
404	            continue;
405	        }
406	        if let Ok(addr) = socket.local_addr() {
407	            if let IpAddr::V4(v4) = addr.ip() {
408	                if !v4.is_loopback() && !v4.is_unspecified() {
409	                    return Some(v4.to_string());
410	                }
411	            }
412	        }
413	    }
414	    None
415	}
416	
417	#[cfg(desktop)]
418	fn current_user() -> String {
419	    std::env::var("USER")
420	        .or_else(|_| std::env::var("USERNAME"))
421	        .unwrap_or_else(|_| "user".to_string())
422	}
423	
424	/// Human-friendly label for this computer, shown on the phone's discovery list.
425	#[cfg(desktop)]
426	fn computer_label() -> String {
427	    // macOS: the user-set "Computer Name" is the friendliest.
428	    if let Ok(out) = Command::new("scutil")
429	        .arg("--get")
430	        .arg("ComputerName")
431	        .output()
432	    {
433	        if out.status.success() {
434	            let name = String::from_utf8_lossy(&out.stdout).trim().to_string();
435	            if !name.is_empty() {
436	                return name;
437	            }
438	        }
439	    }
440	    if let Ok(out) = Command::new("hostname").output() {
441	        if out.status.success() {
442	            let name = String::from_utf8_lossy(&out.stdout)
443	                .trim()
444	                .trim_end_matches(".local")
445	                .to_string();
446	            if !name.is_empty() {
447	                return name;
448	            }
449	        }
450	    }
451	    format!("{}'s computer", current_user())
452	}
453	
454	/// DNS-label-safe version of a free-text name (for the mDNS host name).
455	#[cfg(desktop)]
456	fn sanitize_host_label(value: &str) -> String {
457	    let cleaned: String = value
458	        .chars()
459	        .map(|c| if c.is_ascii_alphanumeric() { c } else { '-' })
460	        .collect();
461	    let trimmed = cleaned.trim_matches('-').to_string();
462	    if trimmed.is_empty() {
463	        "type-sync".to_string()
464	    } else {
465	        trimmed
466	    }
467	}
468	
469	/// Register an mDNS service for the running server. Returns a handle to keep the
470	/// advertisement alive; dropping/unregistering it removes the service.
471	#[cfg(desktop)]
472	fn advertise_mdns(
473	    host: &str,
474	    served_name: &str,
475	    branch: &str,
476	    git_url: &str,
477	) -> Option<MdnsAdvert> {
478	    use mdns_sd::ServiceInfo;
479	
480	    let daemon = ServiceDaemon::new().ok()?;
481	    let label = computer_label();
482	    // host_name owns the A record we publish for `host`; it just has to be unique.
483	    let host_name = format!("{}.local.", sanitize_host_label(&label));
484	    let properties = [
485	        ("url", git_url),
486	        ("branch", branch),
487	        ("path", served_name),
488	        ("name", label.as_str()),
489	    ];
490	    let info = ServiceInfo::new(
491	        MDNS_SERVICE_TYPE,
492	        &label,
493	        &host_name,
494	        host,
495	        LOCAL_SYNC_PORT,
496	        &properties[..],
497	    )
498	    .ok()?;
499	    let fullname = info.get_fullname().to_string();
500	    daemon.register(info).ok()?;
501	    Some(MdnsAdvert { daemon, fullname })
502	}
503	
504	// ── Discovery (all platforms) ────────────────────────────────────────────────
505	
506	/// Browse the local network for advertised sync servers for up to `timeout_ms`.
507	pub fn discover_local_sync_servers_impl(
508	    timeout_ms: u64,
509	) -> Result<Vec<DiscoveredServer>, String> {
510	    let timeout_ms = timeout_ms.clamp(500, 10_000);
511	    let mdns = ServiceDaemon::new().map_err(|e| format!("mDNS init failed: {e}"))?;
512	    let receiver = mdns
513	        .browse(MDNS_SERVICE_TYPE)
514	        .map_err(|e| format!("mDNS browse failed: {e}"))?;
515	
516	    let deadline = Instant::now() + Duration::from_millis(timeout_ms);
517	    let mut found: HashMap<String, DiscoveredServer> = HashMap::new();
518	    loop {
519	        let remaining = deadline.saturating_duration_since(Instant::now());
520	        if remaining.is_zero() {
521	            break;
522	        }
523	        match receiver.recv_timeout(remaining) {
524	            Ok(ServiceEvent::ServiceResolved(info)) => {
525	                if let Some(server) = discovered_from_info(&info) {
526	                    found.insert(info.fullname.clone(), server);
527	                }
528	            }
529	            Ok(_) => {}
530	            Err(_) => break,
531	        }
532	    }
533	    let _ = mdns.shutdown();
534	
535	    let mut servers: Vec<DiscoveredServer> = found.into_values().collect();
536	    servers.sort_by(|a, b| a.name.cmp(&b.name));
537	    Ok(servers)
538	}
539	
540	fn discovered_from_info(info: &mdns_sd::ResolvedService) -> Option<DiscoveredServer> {
541	    let host = info
542	        .get_addresses_v4()
543	        .into_iter()
544	        .next()
545	        .map(|v4| v4.to_string())?;
546	    let path = info.get_property_val_str("path").unwrap_or("notes");
547	    let git_url = info
548	        .get_property_val_str("url")
549	        .map(|value| value.to_string())
550	        .unwrap_or_else(|| format!("git://{host}/{path}"));
551	    let branch = info
552	        .get_property_val_str("branch")
553	        .unwrap_or("main")
554	        .to_string();
555	    let name = info
556	        .get_property_val_str("name")
557	        .map(|value| value.to_string())
558	        .unwrap_or_else(|| info.fullname.clone());
559	    Some(DiscoveredServer {
560	        name,
561	        host,
562	        port: info.port,
563	        git_url,
564	        branch,
565	    })
566	}
567

